{
  "technical_and_design_decisions": [
    "All new API functions will follow the existing Hyperledger Fabric channel configuration API pattern of accepting a protobuf-encoded config transaction as input, modifying it, and returning the modified transaction to enable chaining of multiple config updates as required by acceptance criteria.",
    "All new functions will be exported (capitalized) to be accessible to external users of the API, consistent with existing public API functions.",
    "New functions will reuse existing internal helper functions for config transaction parsing, group/org lookup, and protobuf serialization/deserialization to avoid code duplication and maintain consistency with existing code.",
    "MSP configuration retrieval and certificate revocation functionality will leverage existing Fabric crypto libraries for certificate validation instead of implementing custom crypto logic.",
    "All new functions will return standard Go errors with descriptive messages for invalid inputs to align with existing API error handling patterns.",
    "Policy update functions will support both addition and removal of policies, with validation to prevent duplicate policy additions and removal of non-existent policies.",
    "New org addition functions will automatically add the new org to the appropriate group (application or orderer) in the config transaction, and validate that all required fields are provided before modifying the config."
  ],
  "assumptions": [
    "The Hyperledger Fabric channel configuration API is implemented in Go, the primary language for Fabric core components, so all new code will be written in Go.",
    "The existing Hyperledger Fabric channel configuration API Go codebase is available, fully functional, and the development team is familiar with its structure and existing patterns.",
    "The protobuf schema for channel configuration, organization configuration, and MSP configuration already includes all required fields (e.g., revocation_list in FabricMSPConfig) so no protobuf schema changes are required for this increment.",
    "The existing test infrastructure for the channel config API (unit test framework and example test suite) is already set up and functional, so only new test cases need to be added for the new functionality.",
    "All required external dependencies (Fabric crypto libraries, protobuf tooling) are already included in the project's dependency management, no new external dependencies are needed.",
    "Input config transactions passed to all new functions are assumed to be valid, properly signed channel config transactions as per existing API preconditions; additional base transaction validation is out of scope unless specified in acceptance criteria.",
    "The example tests referenced in acceptance criteria are the existing public example tests for the channel config API, so new examples will follow the same structure and location."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Design new channel config API functions",
      "activity_description": "Define function signatures, input/output types, error handling logic, and alignment with existing Fabric config API patterns for all 8 user stories. Document design decisions for stakeholder review.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2",
      "activity_name": "Implement org configuration retrieval helper (U1)",
      "activity_description": "Implement the function to retrieve application, orderer, or consortium org configuration from a valid config transaction, returning a config.Organization struct. Include error handling for missing orgs, invalid config transaction structure, and unsupported org types.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement application org/group policy update functions (U2)",
      "activity_description": "Implement functions to add or remove policies for application orgs and the application group in a config transaction, returning the modified config transaction for further updates. Include validation for policy names, policy types, and prevention of duplicate policy additions or removal of non-existent policies.",
      "most_likely_effort": 7
    },
    {
      "activity_id": "A4",
      "activity_name": "Implement orderer org/group policy update functions (U3)",
      "activity_description": "Implement functions to add or remove policies for orderer orgs and the orderer group in a config transaction, returning the modified config transaction. Include validation for orderer-specific policy constraints (e.g., orderer endpoint policies).",
      "most_likely_effort": 7
    },
    {
      "activity_id": "A5",
      "activity_name": "Implement consortium org/group policy update functions (U4)",
      "activity_description": "Implement functions to add or remove policies for consortium orgs, the consortiums group, and individual consortium groups in a config transaction, returning the modified config. Include validation for consortium-specific policy rules.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A6",
      "activity_name": "Implement add orderer org to channel config function (U5)",
      "activity_description": "Implement function to add a new orderer org definition to a channel config transaction, returning the modified transaction. Include validation for required orderer org fields (MSP ID, org name, orderer endpoints) and checks for duplicate orderer orgs.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A7",
      "activity_name": "Implement add application org to channel config function (U6)",
      "activity_description": "Implement function to add a new application org definition to a channel config transaction, returning the modified transaction. Include validation for required application org fields (MSP ID, org name) and checks for duplicate application orgs.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A8",
      "activity_name": "Implement MSP configuration retrieval helper (U7)",
      "activity_description": "Implement function to retrieve full MSP configuration (root certificates, intermediate certificates, admin certificates, revocation list, etc.) for a specific org from a config transaction, returning a FabricMSPConfig struct. Include error handling for missing MSP configuration for the specified org.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A9",
      "activity_name": "Implement certificate revocation function (U8)",
      "activity_description": "Implement function to validate that a provided certificate is issued by the target org's MSP (using existing Fabric crypto libraries to verify against root and intermediate CA certificates), then add the certificate to the MSP's revocation list in the config transaction. Return a descriptive error if the certificate is not issued by the MSP.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A10",
      "activity_name": "Write unit tests for all new API functions",
      "activity_description": "Write comprehensive unit tests covering happy paths, edge cases, and error cases for all 9 new functions/helpers implemented in A2-A9. Ensure new code achieves at least 90% test coverage.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A11",
      "activity_name": "Update example tests for new functionality",
      "activity_description": "Update the existing channel config API example test suite to demonstrate usage of all 8 new features per acceptance criteria, following existing example test patterns. Ensure all example tests compile and pass successfully.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A12",
      "activity_name": "Run existing test suite and fix regressions",
      "activity_description": "Execute the full existing channel config API test suite to verify that new changes do not break existing functionality. Fix any regressions or test failures identified.",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 87
  }
}

